{{header2
|title=[[說文解字]]
|section=卷一
|author=許慎
|previous=[[../序|序]]
|next=[[../02|卷二]]
|notes=
}}

==一部==
{| class=wikitable
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''一'''}}
| style="text-align: center;" | [[File:一-小篆.png|75px]]
| style="text-align: center;" | {{+|一}} || {{yw|惟初太始，道立於一，造分天地，化成萬物。凡一之屬皆从一。}}{{*|於悉切。}}
| rowspan="2" style="text-align: center;" | {{+|一}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:弌-seal.png|75px]]
| style="text-align: center;" | {{+|弌}}
| {{yw|古文一。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''元'''}} || style="text-align: center;" | [[File:元-小篆.png|75px]] || style="text-align: center;" | {{+|元}} || {{yw|始也。从一，从兀。}}{{*|徐鍇曰：元者，善之長也，故从一。愚袁切。}} || style="text-align: center;" | {{+|一}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''天'''}} || style="text-align: center;" | [[File:天-小篆.png|75px]] || style="text-align: center;" | {{+|天}} || {{yw|顛也。至高無上。从一大。}}{{*|他前切。}} || style="text-align: center;" | {{+|一}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''丕'''}} || style="text-align: center;" | [[File:丕-seal.png|75px]] || style="text-align: center;" | {{+|丕}} || {{yw|大也。从一，不聲。}}{{*|𢾭悲切。}} || style="text-align: center;" | {{+|一}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''吏'''}} || style="text-align: center;" | [[File:吏-小篆.png|75px]] || style="text-align: center;" | {{+|吏}} || {{yw|治人者也。从一，从史，史亦聲。}}{{*|徐鍇曰：吏之治人，心主於一，故从一。力置切。}} || style="text-align: center;" | {{+|一}}
|-
|}
==丄部==
{| class=wikitable
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''上'''}}
| style="text-align: center;" | [[File:上-1-seal.png|75px]]
| style="text-align: center;" | {{+|丄}} || {{yw|高也。此古文上，指事也。凡丄之屬皆从丄。}}{{*|時掌切。}}
| rowspan="2" style="text-align: center;" | {{+|丄}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:上-2-seal.png|75px]]
| style="text-align: center;" | {{+|上}}
| {{yw|篆文上。}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''帝'''}}
| style="text-align: center;" | [[File:帝-1-seal.png|75px]]
| style="text-align: center;" | {{+|帝}} || {{yw|諦也，王天下之號也。从丄，朿聲。}}{{*|都計切。}}
| rowspan="2" style="text-align: center;" | {{+|丄}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:帝-2-seal.png|75px]]
| style="text-align: center;" | {{+|𢂇}}
| {{yw|古文帝。古文諸丄字皆从一，篆文皆从𠄞。𠄞，古文上字。䇂、示、辰、龍、童、音、章皆从古文丄。}}
|- style="height: 100px;"
| rowspan="4" style="text-align: center;" | {{+|'''旁'''}}
| style="text-align: center;" | [[File:㫄-seal.png|75px]]
| style="text-align: center;" | {{+|㫄}} || {{yw|溥也。从𠄞，闕，方聲。}}{{*|步光切。}}
| rowspan="4" style="text-align: center;" | {{+|丄}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𣃟-seal.png|75px]]
| style="text-align: center;" | {{+|𣃟}}
| {{yw|古文㫄。}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𣃙-seal.png|75px]]
| style="text-align: center;" | {{+|𣃙}}
| {{yw|亦古文㫄。}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:雱-seal.png|75px]]
| style="text-align: center;" | {{+|雱}}
| {{yw|籒文。}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''下'''}}
| style="text-align: center;" | [[File:丅-seal.png|75px]]
| style="text-align: center;" | {{+|丅}} || {{yw|底也。指事。}}{{*|胡雅切。}}
| rowspan="2" style="text-align: center;" | {{+|丄}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:下-小篆.png|75px]]
| style="text-align: center;" | {{+|下}}
| {{yw|篆文下。}}
|-
|}
==示部==
{| class=wikitable
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''示'''}}
| style="text-align: center;" | [[File:示-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|示}} || {{yw|天垂象，見吉凶，所以示人也。从𠄞，}}{{*|𠄞，古文上字。}}{{yw|三垂，日、月、星也。觀乎天文，以察時變。示，神事也。凡示之屬皆从示。}}{{*|神至切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥘅-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|示}}
| {{yw|古文示。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祜'''}} || style="text-align: center;" | [[File:祜-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祜}} || {{yw|上諱。}}{{*|臣鉉等曰：此漢安帝名也，福也，當从示，古聲。候古切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''禮'''}}
| style="text-align: center;" | [[File:禮-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|禮}} || {{yw|履也，所以事神致福也。从示，从豊，豊亦聲。}}{{*|靈啓切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:礼-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|礼}}
| {{yw|古文禮。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禧'''}} || style="text-align: center;" | [[File:禧-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禧}} || {{yw|禮吉也。从示，喜聲。}}{{*|許其切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禛'''}} || style="text-align: center;" | [[File:禛-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禛}} || {{yw|以眞受福也。从示，眞聲。}}{{*|側鄰切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祿'''}} || style="text-align: center;" | [[File:祿-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祿}} || {{yw|福也。从示，彔聲。}}{{*|盧谷切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禠'''}} || style="text-align: center;" | [[File:禠-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禠}} || {{yw|福也。从示，虒聲。}}{{*|息移切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禎'''}} || style="text-align: center;" | [[File:禎-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禎}} || {{yw|祥也。从示，貞聲。}}{{*|陟盈切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祥'''}} || style="text-align: center;" | [[File:祥-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祥}} || {{yw|福也。从示，羊聲。一云善。}}{{*|似羊切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祉'''}} || style="text-align: center;" | [[File:祉-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祉}} || {{yw|福也。从示，止聲。}}{{*|敕里切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''福'''}} || style="text-align: center;" | [[File:福-zhuanwen.png|75px]] || style="text-align: center;" | {{+|福}} || {{yw|祐也。从示，畐聲。}}{{*|方六切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祐'''}} || style="text-align: center;" | [[File:祐-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祐}} || {{yw|助也。从示，右聲。}}{{*|于救切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''祺'''}}
| style="text-align: center;" | [[File:祺-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|祺}} || {{yw|吉也。从示，其聲。}}{{*|渠之切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:禥-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|禥}}
| {{yw|籒文。从基。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祗'''}} || style="text-align: center;" | [[File:祗-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祗}} || {{yw|敬也。从示，氐聲。}}{{*|旨移切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禔'''}} || style="text-align: center;" | [[File:禔-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禔}} || {{yw|安福也。从示，是聲。《易》曰：「禔旣平。」}}{{*|市支切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''神'''}} || style="text-align: center;" | [[File:𥛃-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥛃}} || {{yw|天神，引出萬物者也。从示，申聲。}}{{*|食鄰切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祇'''}} || style="text-align: center;" | [[File:祇-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祇}} || {{yw|地祇，提出萬物者也。从示，氏聲。}}{{*|巨支切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祕'''}} || style="text-align: center;" | [[File:祕-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祕}} || {{yw|神也。从示，必聲。}}{{*|兵媚切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''齋'''}}
| style="text-align: center;" | [[File:𥚪-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥚪}} || {{yw|戒，潔也。从示，齊省聲。}}{{*|側皆切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥜷-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥜷}}
| {{yw|籒文齋。从𥜹省。}}{{*|𥜹音禱。}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''禋'''}}
| style="text-align: center;" | [[File:𥛿-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥛿}} || {{yw|潔祀也。一曰精意以享爲禋。从示，垔聲。}}{{*|於真切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𡫻-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𡫻}}
| {{yw|籒文。从宀。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祭'''}} || style="text-align: center;" | [[File:祭-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祭}} || {{yw|祭祀也。从示，以手持肉。}}{{*|子例切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''祀'''}}
| style="text-align: center;" | [[File:祀-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|祀}} || {{yw|祭無已也。从示，巳聲。}}{{*|詳里切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:禩-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|禩}}
| {{yw|祀或从異。}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''祡'''}}
| style="text-align: center;" | [[File:祡-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|祡}} || {{yw|燒祡燓燎，以祭天神。从示，此聲。《虞書》曰：「至于岱宗，祡。」}}{{*|仕皆切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥚨-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥚨}}
| {{yw|古文祡。从隋省。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禷'''}} || style="text-align: center;" | [[File:禷-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禷}} || {{yw|以事類祭天神。从示，類聲。}}{{*|力遂切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祪'''}} || style="text-align: center;" | [[File:祪-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祪}} || {{yw|祔、祪，祖也。从示，危聲。}}{{*|過委切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祔'''}} || style="text-align: center;" | [[File:祔-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祔}} || {{yw|後死者合食於先祖。从示，付聲。}}{{*|符遇切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祖'''}} || style="text-align: center;" | [[File:祖-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祖}} || {{yw|始廟也。从示，且聲。}}{{*|則古切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''𥛱'''}}
| style="text-align: center;" | [[File:𥛱-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥛱}} || {{yw|門內祭，先祖所徬徨。从示，彭聲。《詩》曰：「祝祭于𥛱。」}}{{*|補盲切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:祊-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|祊}}
| {{yw|𥛱或从方。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祰'''}} || style="text-align: center;" | [[File:祰-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祰}} || {{yw|告祭也。从示，从吿聲。}}{{*|苦浩切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祏'''}} || style="text-align: center;" | [[File:祏-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祏}} || {{yw|宗廟主也。周禮有郊宗石室。一曰大夫以石爲主。从示，从石，石亦聲。}}{{*|常隻切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''䃾'''}} || style="text-align: center;" | [[File:䃾-zhuanwen.png|75px]] || style="text-align: center;" | {{+|䃾}} || {{yw|以豚祠司命。从示，比聲。漢律曰：「祠䃾司命。」}}{{*|卑履切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祠'''}} || style="text-align: center;" | [[File:祠-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祠}} || {{yw|春祭曰祠，品物少，多文詞也。从示，司聲。仲春之月，祠不用犧牲，用圭璧及皮幣。}}{{*|似茲切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''礿'''}} || style="text-align: center;" | [[File:礿-zhuanwen.png|75px]] || style="text-align: center;" | {{+|礿}} || {{yw|夏祭也。从示，勺聲。}}{{*|以灼切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禘'''}} || style="text-align: center;" | [[File:禘-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禘}} || {{yw|諦祭也。从示，帝聲。周禮曰五歲一禘。}}{{*|特計切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祫'''}} || style="text-align: center;" | [[File:祫-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祫}} || {{yw|大合祭先祖親疏遠近也。从示、合。周禮曰三歲一祫。}}{{*|侯夾切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祼'''}} || style="text-align: center;" | [[File:祼-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祼}} || {{yw|灌祭也。从示，果聲。}}{{*|古玩切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''䄟'''}} || style="text-align: center;" | [[File:䄟-zhuanwen.png|75px]] || style="text-align: center;" | {{+|䄟}} || {{yw|數祭也。从示，毳聲。讀若舂麥爲䄟之䄟。}}{{*|臣鉉等曰：「舂麥爲䄟」，今無此語，且非異文，所未詳也。此芮切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祝'''}} || style="text-align: center;" | [[File:祝-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祝}} || {{yw|祭主贊詞者。从示，从人口，一曰从兌省。《易》曰：「兌，爲口爲巫。」}}{{*|之六切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''𥛅'''}} || style="text-align: center;" | [[File:𥛅-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥛽}} || {{yw|祝𥛽也。从示，畱聲。}}{{*|力救切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祓'''}} || style="text-align: center;" | [[File:祓-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祓}} || {{yw|除惡祭也。从示，犮聲。}}{{*|𢾭勿切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祈'''}} || style="text-align: center;" | [[File:祈-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祈}} || {{yw|求福也。从示，斤聲。}}{{*|渠稀切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="3" style="text-align: center;" | {{+|'''禱'''}}
| style="text-align: center;" | [[File:𥜣-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥜣}} || {{yw|告事求福也。从示，壽聲。}}{{*|都浩切。}}
| rowspan="3" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥛇-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥛇}}
| {{yw|禱或省。}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥜹-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥜹}}
| {{yw|籒文禱。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禜'''}} || style="text-align: center;" | [[File:禜-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禜}} || {{yw|設緜蕝爲營，以禳風雨雪霜水旱癘疫於日月星辰山川也。从示，榮省聲。一曰禜衞，使灾不生。《禮記》曰：「雩禜，祭水旱。」}}{{*|爲命切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禳'''}} || style="text-align: center;" | [[File:禳-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禳}} || {{yw|磔禳祀，除癘殃也。古者燧人禜子所造。从示，襄聲。}}{{*|汝羊切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禬'''}} || style="text-align: center;" | [[File:禬-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禬}} || {{yw|會福祭也。从示，从會，會亦聲。《周禮》曰：「禬之祝號。」}}{{*|古外切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禪'''}} || style="text-align: center;" | [[File:禪-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禪}} || {{yw|祭天也。从示，單聲。}}{{*|時戰切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禦'''}} || style="text-align: center;" | [[File:禦-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禦}} || {{yw|祀也。从示，御聲。}}{{*|魚舉切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''䄆'''}} || style="text-align: center;" | [[File:䄆-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥙱}} || {{yw|祀也。从示，𠯑聲。}}{{*|古末切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禖'''}} || style="text-align: center;" | [[File:禖-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禖}} || {{yw|祭也。从示，某聲。}}{{*|莫桮切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''𥚩'''}} || style="text-align: center;" | [[File:𥚩-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥚩}} || {{yw|祭具也。从示，胥聲。}}{{*|私呂切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祳'''}} || style="text-align: center;" | [[File:祳-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祳}} || {{yw|社肉，盛以蜃，故謂之祳，天子所以親遺同姓。从示，辰聲。《春秋傳》曰：「石尙來歸祳。」}}{{*|時忍切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祴'''}} || style="text-align: center;" | [[File:祴-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祴}} || {{yw|宗廟奏祴樂。从示，戒聲。}}{{*|古哀切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禡'''}} || style="text-align: center;" | [[File:禡-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禡}} || {{yw|師行所止，恐有慢其神，下而祀之曰禡。从示，馬聲。周禮曰禡於所征之地。}}{{*|莫駕切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''禂'''}}
| style="text-align: center;" | [[File:禂-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|禂}} || {{yw|禱牲馬祭也。从示，周聲。《詩》曰：「旣禡旣禂。」}}{{*|都皓切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𩦑-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𩦑}}
| {{yw|或从馬，壽省聲。}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''社'''}}
| style="text-align: center;" | [[File:社-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|社}} || {{yw|地主也。从示、土。《春秋傳》曰：「共工之子句龍爲社神。」周禮，二十五家爲社，各樹其土所宜之木。}}{{*|常者切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥙭-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥙭}}
| {{yw|古文社。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禓'''}} || style="text-align: center;" | [[File:禓-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禓}} || {{yw|道上祭。从示，昜聲。}}{{*|與章切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祲'''}} || style="text-align: center;" | [[File:祲-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥛆}} || {{yw|精氣感祥。从示，㑴省聲。《春秋傳》曰：「見赤黑之𥛆。」}}{{*|子林切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禍'''}} || style="text-align: center;" | [[File:禍-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禍}} || {{yw|害也，神不福也。从示，咼聲。}}{{*|胡果切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| rowspan="2" style="text-align: center;" | {{+|'''祟'''}}
| style="text-align: center;" | [[File:祟-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|祟}} || {{yw|神禍也。从示，从出。}}{{*|雖遂切。}}
| rowspan="2" style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | [[File:𥜱-zhuanwen.png|75px]]
| style="text-align: center;" | {{+|𥜱}}
| {{yw|籒文祟。从𥜹省。}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''䄏'''}} || style="text-align: center;" | [[File:䄏-zhuanwen.png|75px]] || style="text-align: center;" | {{+|䄏}} || {{yw|地反物爲䄏也。从示，芺聲。}}{{*|於喬切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祘'''}} || style="text-align: center;" | [[File:祘-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祘}} || {{yw|明視以筭之。从二示。逸《周書》曰：「士分民之祘。」均分以祘之也。讀若筭。}}{{*|蘇貫切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禁'''}} || style="text-align: center;" | [[File:禁-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禁}} || {{yw|吉凶之忌也。从示，林聲。}}{{*|居蔭切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禫'''}} || style="text-align: center;" | [[File:禫-zhuanwen.png|75px]] || style="text-align: center;" | {{+|𥜸}} || {{yw|除服祭也。从示，覃聲。}}{{*|徒感切。}} || style="text-align: center;" | {{+|示}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''禰'''}} || style="text-align: center;" | [[File:禰-zhuanwen.png|75px]] || style="text-align: center;" | {{+|禰}} || {{*|親廟也。从示，爾聲。一本云古文𥜬也。泥米切。}} || style="text-align: center;" | {{+|示}}{{*|新附}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祧'''}} || style="text-align: center;" | [[File:祧-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祧}} || {{*|遷廟也。从示，兆聲。他彫切。}} || style="text-align: center;" | {{+|示}}{{*|新附}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祆'''}} || style="text-align: center;" | [[File:祆-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祆}} || {{*|胡神也。从示，天聲。火千切。}} || style="text-align: center;" | {{+|示}}{{*|新附}}
|- style="height: 100px;"
| style="text-align: center;" | {{+|'''祚'''}} || style="text-align: center;" | [[File:祚-zhuanwen.png|75px]] || style="text-align: center;" | {{+|祚}} || {{*|福也。从示，乍聲。臣鉉等曰：凡祭必受胙，胙卽福也。此字後人所加。徂故切。}} || style="text-align: center;" | {{+|示}}{{*|新附}}
|-
|}
